for (a, b, c) in [
    let d = b * b - 4 * a * c;
    if d > 0 {
        let root = f64::from(d).sqrt();
        let x = (f64::from(-b) + root) / f64::from(2 * a);
        let y = (f64::from(-b) - root) / f64::from(2 * a);
        println!("x1 = {:.4}, x2 = {:.4}", x.max(y), x.min(y));
